+func (s *EtcdServer) rangeStream(ctx context.Context, r *pb.RangeRequest, rs pb.KV_RangeStreamServer) error {
+	if r.CountOnly {
+		resp, _, err := txn.Range(ctx, s.Logger(), s.KV(), r, false)
+		if err != nil {
+			return err
+		}
+		out := &pb.RangeResponse{
+			Header: &pb.ResponseHeader{Revision: resp.Header.Revision},
+			Count:  resp.Count,
+		}
+		return rs.Send(&pb.RangeStreamResponse{RangeResponse: out})
+	}
+
+	totalLimit := r.Limit
+	if totalLimit == 0 {
+		totalLimit = math.MaxInt64
+	}
+	r.Limit = min(initialStreamChunkLimit, totalLimit)
+	if r.Limit < 1 {
+		r.Limit = 1
+	}
+
+	count := int64(0)
+	var headerRev int64
+	for {
+		resp, _, err := txn.Range(ctx, s.Logger(), s.KV(), r, false)
+		if err != nil {
+			return err
+		}
+		// Pin an implicit revision to the revision returned by the first chunk.
+		if headerRev == 0 {
+			headerRev = resp.Header.Revision
+			if r.Revision == 0 {
+				r.Revision = headerRev
+			}
+		}
+		count += int64(len(resp.Kvs))
+
+		var nextKey []byte
+		if resp.More {
+			nextKey = append(resp.Kvs[len(resp.Kvs)-1].Key, '\x00')
+		}
+		out := &pb.RangeResponse{Kvs: resp.Kvs}
+		done := !resp.More || count == totalLimit
+		if done {
+			out.Header = &pb.ResponseHeader{Revision: headerRev}
+			out.More = resp.More
+			out.Count = count
+			if resp.More {
+				remaining, cerr := txn.Count(ctx, s.Logger(), s.KV(), nextKey, r.RangeEnd, r.Revision)
+				if cerr != nil {
+					return cerr
+				}
+				out.Count += remaining
+			}
+		}
+		if err := rs.Send(&pb.RangeStreamResponse{RangeResponse: out}); err != nil {
+			return err
+		}
+		if done {
+			return nil
+		}
+
+		r.Key = nextKey
+		r.Limit = min(adjustChunkLimit(r.Limit, resp.Size(), int(s.Cfg.MaxRequestBytes)), totalLimit-count)
+		if r.Limit < 1 {
+			r.Limit = 1
+		}
+	}
+}
+
+const initialStreamChunkLimit int64 = 10
+
+// adjustChunkLimit moves the next chunk's limit toward MaxRequestBytes.
+// It always returns a positive value because zero and negative Range limits
+// both mean an unbounded request.
+func adjustChunkLimit(lastLimit int64, lastSize, targetSize int) int64 {
+	if lastLimit < 1 {
+		return 1
+	}
+	switch {
+	case lastSize < targetSize/2:
+		if lastLimit > math.MaxInt64/2 {
+			return math.MaxInt64
+		}
+		lastLimit *= 2
+	case lastSize > targetSize*2:
+		lastLimit /= 2
+	}
+	if lastLimit < 1 {
+		return 1
+	}
+	return lastLimit
+}
